public async Task<IReadOnlyList<OrderDto>> GetRecentOrdersAsync(
    Guid customerId,
    DateTime since,
    CancellationToken ct)
{
    return await _context.Orders
        .Where(o => o.CustomerId == customerId && o.CreatedAt >= since)
        .Include(o => o.Items)
        .OrderByDescending(o => o.CreatedAt)
        .Select(o => new OrderDto
        {
            Id = o.Id,
            Total = o.Total,
            ItemCount = o.Items.Count,
            CreatedAt = o.CreatedAt
        })
        .AsNoTracking()
        .ToListAsync(ct);
}

public async Task<IReadOnlyList<OrderWithItems>> GetRecentOrdersAsync(
    Guid customerId,
    DateTime since,
    CancellationToken ct)
{
    const string sql = @"
        SELECT o.Id, o.Total, o.CreatedAt, i.Id, i.Sku, i.Quantity, i.Price
        FROM Orders o
        INNER JOIN OrderItems i ON i.OrderId = o.Id
        WHERE o.CustomerId = @CustomerId AND o.CreatedAt >= @Since
        ORDER BY o.CreatedAt DESC";

    var orderLookup = new Dictionary<Guid, OrderWithItems>();

    await _connection.QueryAsync<Order, OrderItem, OrderWithItems>(
        sql,
        (order, item) =>
        {
            if (!orderLookup.TryGetValue(order.Id, out var existing))
            {
                existing = new OrderWithItems
                {
                    Id = order.Id,
                    Total = order.Total,
                    CreatedAt = order.CreatedAt,
                    Items = new List<OrderItem>()
                };
                orderLookup.Add(order.Id, existing);
            }
            existing.Items.Add(item);
            return existing;
        },
        new { CustomerId = customerId, Since = since },
        splitOn: "Id");

    return orderLookup.Values.ToList();
}
